require 'json';require 'open3';require 'fileutils';root=File.expand_path('..',__dir__);s=File.read(File.join(root,'server/GameCommon/src/main/java/com/aoo/bcg/common/lifecycle/ManagedAsyncExecutor.java'));scheduler=File.read(File.join(root,'server/LegacyCommon/src/com/ddm/server/LegacyCommon/task/ScheduledExecutorServiceMgr.java'));admin=File.read(File.join(root,'server/AdminApi/src/main/java/com/aoo/bcg/admin/AdminApiApplication.java'));jdk=File.expand_path('../.toolchains/jdk-26.0.2.1.jdk/Contents/Home',root);env={'JAVA_HOME'=>jdk,'PATH'=>"#{jdk}/bin:#{ENV['PATH']}"};o,e,st=Open3.capture3(env,'./mvnw','-pl','server/GameCommon','-am','-Dtest=ManagedAsyncExecutorTest','-Dsurefire.failIfNoSpecifiedTests=false','test','-q',chdir:root);c={'named_executor'=>s.include?('ManagedAsyncExecutor'),'context_propagation'=>s.include?('CONTEXT.set(captured)'),'failure_reporting'=>s.include?('failureSink.accept'),'graceful_shutdown'=>s.include?('awaitTermination')&&scheduler.include?('awaitTermination'),'interrupt_restored'=>s.include?('Thread.currentThread().interrupt()'),'admin_executor_closed'=>admin.include?('requestExecutor.close()'),'tests_passed'=>st.success?};r={'task'=>'JAVA10','passed'=>c.values.all?,'checks'=>c,'testStdout'=>o.strip,'testStderr'=>e.strip};p=File.join(root,'work/audit/async-lifecycle.json');FileUtils.mkdir_p(File.dirname(p));File.write(p,JSON.pretty_generate(r)+"\n");puts JSON.generate(r);exit(r['passed'] ? 0 : 1)
